/* ==========================================================================
   電卓アプリ (Calculator App) スタイル定義
   ========================================================================== */

:root {
  --bg-app: #0f172a;
  --bg-card: #1e293b;
  --bg-display: #090d16;
  --bg-keypad: #1e293b;

  --bg-btn-number: #334155;
  --bg-btn-number-hover: #475569;
  --bg-btn-number-active: #64748b;

  --bg-btn-action: #475569;
  --bg-btn-action-hover: #64748b;

  --bg-btn-operator: #f59e0b;
  --bg-btn-operator-hover: #d97706;
  --bg-btn-operator-active: #ffffff;

  --bg-btn-equals: #10b981;
  --bg-btn-equals-hover: #059669;

  --bg-history-panel: #141d2e;
  --bg-history-item: #1e293b;
  --bg-history-item-hover: #2d3d57;

  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --text-dim: #64748b;
  --text-operator-active: #b45309;
  --text-equals: #ffffff;

  --border-color: #334155;
  --radius-card: 24px;
  --radius-btn: 16px;
  --radius-display: 16px;

  --shadow-card: 0 20px 40px -15px rgba(0, 0, 0, 0.6), 0 0 0 1px rgba(255, 255, 255, 0.08);
  --shadow-btn: 0 4px 6px -1px rgba(0, 0, 0, 0.2), 0 2px 4px -2px rgba(0, 0, 0, 0.2);
  --shadow-btn-pressed: 0 1px 2px 0 rgba(0, 0, 0, 0.3) inset;
  --focus-ring: 0 0 0 2px #0f172a, 0 0 0 4px #38bdf8;

  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", "Hiragino Kaku Gothic ProN", "Yu Gothic", "Meiryo", sans-serif;
  --font-mono: "SF Mono", "Roboto Mono", "Courier New", monospace;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-app);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  line-height: 1.5;
  user-select: none;
  -webkit-user-select: none;
}

/* --------------------------------------------------------------------------
   全体コンテナ
   -------------------------------------------------------------------------- */
.calculator-app {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 100%;
  max-width: 860px;
  margin: 0 auto;
  gap: 24px;
}

/* --------------------------------------------------------------------------
   電卓カード (本体 + 履歴パネル)
   -------------------------------------------------------------------------- */
.calculator-card {
  display: flex;
  flex-direction: column;
  background-color: var(--bg-card);
  border-radius: var(--radius-card);
  box-shadow: var(--shadow-card);
  width: 100%;
  max-width: 380px;
  overflow: hidden;
  border: 1px solid var(--border-color);
  transition: all 0.3s ease;
}

@media (min-width: 768px) {
  .calculator-card {
    flex-direction: row;
    max-width: 760px;
  }
}

/* --------------------------------------------------------------------------
   ディスプレイ
   -------------------------------------------------------------------------- */
.display-container {
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: flex-end;
  background-color: var(--bg-display);
  padding: 24px 20px 16px 20px;
  min-height: 110px;
  border-bottom: 1px solid var(--border-color);
  word-break: break-all;
  overflow: hidden;
}

.display-history-expr {
  font-family: var(--font-mono);
  font-size: 0.95rem;
  color: var(--text-muted);
  min-height: 1.4rem;
  margin-bottom: 4px;
  opacity: 0.85;
  letter-spacing: 0.05em;
  text-align: right;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 100%;
}

.display-current {
  font-family: var(--font-mono);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--text-main);
  text-align: right;
  line-height: 1.1;
  letter-spacing: -0.02em;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* --------------------------------------------------------------------------
   キーパッド
   -------------------------------------------------------------------------- */
.keypad-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  padding: 16px;
  background-color: var(--bg-keypad);
  flex: 1;
}

/* 共通ボタンスタイル */
.btn-calc {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 60px;
  border: none;
  border-radius: var(--radius-btn);
  font-size: 1.35rem;
  font-weight: 600;
  font-family: var(--font-mono);
  cursor: pointer;
  box-shadow: var(--shadow-btn);
  outline: none;
  transition: background-color 0.15s ease, transform 0.08s ease, box-shadow 0.15s ease;
  touch-action: manipulation;
}

.btn-calc:active {
  transform: scale(0.96);
  box-shadow: var(--shadow-btn-pressed);
}

.btn-calc:focus-visible {
  outline: 2px solid #38bdf8;
  outline-offset: 2px;
  box-shadow: var(--focus-ring);
}

/* 数字ボタン */
.btn-number {
  background-color: var(--bg-btn-number);
  color: var(--text-main);
}

.btn-number:hover {
  background-color: var(--bg-btn-number-hover);
}

.btn-number:active {
  background-color: var(--bg-btn-number-active);
}

/* 機能・アクションボタン (AC, +/-, %) */
.btn-action {
  background-color: var(--bg-btn-action);
  color: var(--text-main);
}

.btn-action:hover {
  background-color: var(--bg-btn-action-hover);
}

/* 演算子ボタン (+, -, ×, ÷) */
.btn-operator {
  background-color: var(--bg-btn-operator);
  color: #ffffff;
  font-size: 1.5rem;
}

.btn-operator:hover {
  background-color: var(--bg-btn-operator-hover);
}

.btn-operator-active {
  background-color: var(--bg-btn-operator-active);
  color: var(--text-operator-active);
  box-shadow: 0 0 12px rgba(245, 158, 11, 0.7);
}

/* 等号ボタン (=) */
.btn-equals {
  background-color: var(--bg-btn-equals);
  color: var(--text-equals);
  font-size: 1.5rem;
}

.btn-equals:hover {
  background-color: var(--bg-btn-equals-hover);
}

/* ゼロボタン (横幅2列分) */
.btn-zero {
  grid-column: span 2;
  justify-content: flex-start;
  padding-left: 26px;
}

/* --------------------------------------------------------------------------
   計算履歴パネル
   -------------------------------------------------------------------------- */
.history-panel {
  display: flex;
  flex-direction: column;
  background-color: var(--bg-history-panel);
  border-top: 1px solid var(--border-color);
  padding: 16px;
  min-height: 220px;
  max-height: 280px;
}

@media (min-width: 768px) {
  .history-panel {
    border-top: none;
    border-left: 1px solid var(--border-color);
    width: 300px;
    min-height: auto;
    max-height: 480px;
  }
}

.history-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 10px;
}

.history-title {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-main);
  letter-spacing: 0.05em;
}

.history-clear-btn {
  background: transparent;
  border: 1px solid var(--border-color);
  color: var(--text-muted);
  font-size: 0.8rem;
  padding: 4px 10px;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.2s ease;
  outline: none;
}

.history-clear-btn:hover:not(:disabled) {
  background-color: rgba(239, 68, 68, 0.15);
  border-color: #ef4444;
  color: #ef4444;
}

.history-clear-btn:focus-visible {
  outline: 2px solid #ef4444;
  outline-offset: 2px;
}

.history-clear-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.history-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  overflow-y: auto;
  padding-right: 4px;
  flex: 1;
}

/* スクロールバーのスタイル */
.history-list::-webkit-scrollbar {
  width: 6px;
}

.history-list::-webkit-scrollbar-track {
  background: transparent;
}

.history-list::-webkit-scrollbar-thumb {
  background-color: var(--border-color);
  border-radius: 3px;
}

.history-list::-webkit-scrollbar-thumb:hover {
  background-color: var(--text-dim);
}

.history-item {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  padding: 10px 12px;
  background-color: var(--bg-history-item);
  border-radius: 10px;
  cursor: pointer;
  transition: background-color 0.15s ease, transform 0.1s ease;
  border: 1px solid transparent;
  outline: none;
}

.history-item:hover {
  background-color: var(--bg-history-item-hover);
  border-color: rgba(255, 255, 255, 0.08);
  transform: translateX(-2px);
}

.history-item:active {
  transform: translateX(0);
}

.history-item:focus-visible {
  outline: 2px solid #38bdf8;
  outline-offset: 2px;
  border-color: #38bdf8;
}

.history-expr {
  font-family: var(--font-mono);
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-bottom: 2px;
  text-align: right;
  word-break: break-all;
}

.history-result {
  font-family: var(--font-mono);
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-main);
  text-align: right;
  word-break: break-all;
}

.empty-history-text {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
  color: var(--text-dim);
  font-size: 0.85rem;
  text-align: center;
  padding: 24px 0;
}

/* --------------------------------------------------------------------------
   画面の高さが小さいデバイス向けのレスポンシブスタイル
   -------------------------------------------------------------------------- */
@media (max-height: 700px) {
  body {
    padding: 8px;
  }

  .calculator-app {
    gap: 12px;
  }

  .display-container {
    padding: 16px 16px 12px 16px;
    min-height: 84px;
  }

  .display-history-expr {
    font-size: 0.85rem;
    min-height: 1.2rem;
    margin-bottom: 2px;
  }

  .display-current {
    font-size: 2rem;
  }

  .keypad-grid {
    gap: 8px;
    padding: 12px;
  }

  .btn-calc {
    height: 48px;
    font-size: 1.2rem;
    border-radius: 12px;
  }

  .btn-operator,
  .btn-equals {
    font-size: 1.35rem;
  }

  .btn-zero {
    padding-left: 20px;
  }

  .history-panel {
    min-height: 150px;
    max-height: 200px;
    padding: 12px;
  }
}

export type Operator = '+' | '-' | '×' | '÷';

export type OperatorType = Operator | null;

export interface CalculationHistory {
  id: string;
  expression: string;
  result: string;
  timestamp: string;
}

export interface KeypadButtonConfig {
  id: string;
  label: string;
  className: string;
  ariaLabel: string;
  onClick: () => void;
}

interface DisplayProps {
  expression?: string;
  currentValue?: string;
}

const Display = ({ expression = '', currentValue = '0' }: DisplayProps) => {
  const getFontSize = (text: string) => {
    const len = text.length;
    if (len > 12) return '1.5rem';
    if (len > 9) return '1.85rem';
    if (len > 7) return '2.15rem';
    return '2.5rem';
  };

  return (
    <div className="display-container">
      <div className="display-history-expr" title={expression}>
        {expression}
      </div>
      <div
        className="display-current"
        title={currentValue}
        role="status"
        aria-live="polite"
        style={{ fontSize: getFontSize(currentValue) }}
      >
        {currentValue}
      </div>
    </div>
  );
};

export default Display;

import { OperatorType } from '../types';

interface KeypadProps {
  onDigit?: (digit: string) => void;
  onDecimal?: () => void;
  onOperator?: (op: '+' | '-' | '×' | '÷') => void;
  onEquals?: () => void;
  onClear?: () => void;
  onAllClear?: () => void;
  onToggleSign?: () => void;
  onPercent?: () => void;
  isClearAll?: boolean;
  activeOperator?: OperatorType;
}

interface ButtonConfig {
  id: string;
  label: string;
  className: string;
  ariaLabel: string;
  onClick: () => void;
}

const Keypad = ({
  onDigit,
  onDecimal,
  onOperator,
  onEquals,
  onClear,
  onAllClear,
  onToggleSign,
  onPercent,
  isClearAll = true,
  activeOperator = null,
}: KeypadProps) => {
  const handleClearClick = () => {
    if (isClearAll) {
      onAllClear?.();
    } else {
      onClear?.();
    }
  };

  const getOperatorClass = (op: '+' | '-' | '×' | '÷') => {
    return activeOperator === op
      ? 'btn-calc btn-operator btn-operator-active'
      : 'btn-calc btn-operator';
  };

  const buttons: ButtonConfig[] = [
    {
      id: 'clear',
      label: isClearAll ? 'AC' : 'C',
      className: 'btn-calc btn-action',
      ariaLabel: isClearAll ? 'オールクリア' : 'クリア',
      onClick: handleClearClick,
    },
    {
      id: 'toggle-sign',
      label: '±',
      className: 'btn-calc btn-action',
      ariaLabel: '符号反転',
      onClick: () => onToggleSign?.(),
    },
    {
      id: 'percent',
      label: '%',
      className: 'btn-calc btn-action',
      ariaLabel: 'パーセント',
      onClick: () => onPercent?.(),
    },
    {
      id: 'divide',
      label: '÷',
      className: getOperatorClass('÷'),
      ariaLabel: '割る',
      onClick: () => onOperator?.('÷'),
    },
    {
      id: 'num-7',
      label: '7',
      className: 'btn-calc btn-number',
      ariaLabel: '7',
      onClick: () => onDigit?.('7'),
    },
    {
      id: 'num-8',
      label: '8',
      className: 'btn-calc btn-number',
      ariaLabel: '8',
      onClick: () => onDigit?.('8'),
    },
    {
      id: 'num-9',
      label: '9',
      className: 'btn-calc btn-number',
      ariaLabel: '9',
      onClick: () => onDigit?.('9'),
    },
    {
      id: 'multiply',
      label: '×',
      className: getOperatorClass('×'),
      ariaLabel: '掛ける',
      onClick: () => onOperator?.('×'),
    },
    {
      id: 'num-4',
      label: '4',
      className: 'btn-calc btn-number',
      ariaLabel: '4',
      onClick: () => onDigit?.('4'),
    },
    {
      id: 'num-5',
      label: '5',
      className: 'btn-calc btn-number',
      ariaLabel: '5',
      onClick: () => onDigit?.('5'),
    },
    {
      id: 'num-6',
      label: '6',
      className: 'btn-calc btn-number',
      ariaLabel: '6',
      onClick: () => onDigit?.('6'),
    },
    {
      id: 'subtract',
      label: '-',
      className: getOperatorClass('-'),
      ariaLabel: '引く',
      onClick: () => onOperator?.('-'),
    },
    {
      id: 'num-1',
      label: '1',
      className: 'btn-calc btn-number',
      ariaLabel: '1',
      onClick: () => onDigit?.('1'),
    },
    {
      id: 'num-2',
      label: '2',
      className: 'btn-calc btn-number',
      ariaLabel: '2',
      onClick: () => onDigit?.('2'),
    },
    {
      id: 'num-3',
      label: '3',
      className: 'btn-calc btn-number',
      ariaLabel: '3',
      onClick: () => onDigit?.('3'),
    },
    {
      id: 'add',
      label: '+',
      className: getOperatorClass('+'),
      ariaLabel: '足す',
      onClick: () => onOperator?.('+'),
    },
    {
      id: 'num-0',
      label: '0',
      className: 'btn-calc btn-number btn-zero',
      ariaLabel: '0',
      onClick: () => onDigit?.('0'),
    },
    {
      id: 'decimal',
      label: '.',
      className: 'btn-calc btn-number',
      ariaLabel: '小数点',
      onClick: () => onDecimal?.(),
    },
    {
      id: 'equals',
      label: '=',
      className: 'btn-calc btn-equals',
      ariaLabel: '等号',
      onClick: () => onEquals?.(),
    },
  ];

  return (
    <div className="keypad-grid">
      {buttons.map((btn) => (
        <button
          key={btn.id}
          type="button"
          className={btn.className}
          aria-label={btn.ariaLabel}
          onClick={btn.onClick}
        >
          {btn.label}
        </button>
      ))}
    </div>
  );
};

export default Keypad;

import { CalculationHistory } from '../types';

interface HistoryListProps {
  history?: CalculationHistory[];
  onSelectHistory?: (item: CalculationHistory) => void;
  onClearHistory?: () => void;
}

const HistoryList = ({
  history = [],
  onSelectHistory,
  onClearHistory,
}: HistoryListProps) => {
  const hasHistory = history.length > 0;

  return (
    <div className="history-panel">
      <div className="history-header">
        <span className="history-title">計算履歴</span>
        <button
          type="button"
          className="history-clear-btn"
          disabled={!hasHistory}
          onClick={() => onClearHistory?.()}
        >
          履歴クリア
        </button>
      </div>

      <div className="history-list">
        {!hasHistory ? (
          <div className="empty-history-text">計算履歴はありません</div>
        ) : (
          history.map((item) => (
            <button
              key={item.id}
              type="button"
              className="history-item"
              onClick={() => onSelectHistory?.(item)}
              title="クリックしてこの数値を再利用"
              style={{
                width: '100%',
                background: 'var(--bg-history-item)',
                border: '1px solid transparent',
                textAlign: 'right',
                font: 'inherit',
                color: 'inherit',
              }}
            >
              <div
                style={{
                  fontSize: '0.75rem',
                  color: 'var(--text-dim)',
                  marginBottom: '2px',
                }}
              >
                {item.timestamp}
              </div>
              <div className="history-expr">{item.expression}</div>
              <div className="history-result">{item.result}</div>
            </button>
          ))
        )}
      </div>
    </div>
  );
};

export default HistoryList;

import { useState, useEffect, useCallback } from 'react';
import { CalculationHistory, OperatorType } from './types';
import Display from './components/Display';
import Keypad from './components/Keypad';
import HistoryList from './components/HistoryList';
import './index.css';

const MAX_DIGITS = 12;

const generateId = (): string => {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  return `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
};

const sanitizeNumber = (num: number): string => {
  if (isNaN(num) || !isFinite(num)) {
    return 'エラー';
  }
  // 浮動小数点丸め
  const rounded = parseFloat(num.toPrecision(12));
  return String(rounded);
};

const App = () => {
  const [currentValue, setCurrentValue] = useState<string>('0');
  const [previousValue, setPreviousValue] = useState<string | null>(null);
  const [operator, setOperator] = useState<OperatorType>(null);
  const [waitingForOperand, setWaitingForOperand] = useState<boolean>(false);
  const [expression, setExpression] = useState<string>('');
  const [history, setHistory] = useState<CalculationHistory[]>([]);
  const [isClearAll, setIsClearAll] = useState<boolean>(true);

  // 履歴追加処理の共通化
  const addHistoryItem = useCallback((expr: string, resultStr: string) => {
    const newHistoryItem: CalculationHistory = {
      id: generateId(),
      expression: expr,
      result: resultStr,
      timestamp: new Date().toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' }),
    };
    setHistory((prev) => [newHistoryItem, ...prev]);
  }, []);

  // 四則計算の実行処理
  const executeCalculation = useCallback(
    (prevStr: string, currentStr: string, op: OperatorType): { resultStr: string; error: boolean } => {
      const prev = parseFloat(prevStr);
      const current = parseFloat(currentStr);

      if (isNaN(prev) || isNaN(current)) {
        return { resultStr: 'エラー', error: true };
      }

      let res = 0;
      switch (op) {
        case '+':
          res = prev + current;
          break;
        case '-':
          res = prev - current;
          break;
        case '×':
          res = prev * current;
          break;
        case '÷':
          if (current === 0) {
            return { resultStr: 'エラー', error: true };
          }
          res = prev / current;
          break;
        default:
          return { resultStr: currentStr, error: false };
      }

      const sanitized = sanitizeNumber(res);
      if (sanitized === 'エラー') {
        return { resultStr: 'エラー', error: true };
      }
      return { resultStr: sanitized, error: false };
    },
    []
  );

  // 数字入力
  const handleDigit = useCallback(
    (digit: string) => {
      if (currentValue === 'エラー') {
        setCurrentValue(digit);
        setWaitingForOperand(false);
        setIsClearAll(false);
        return;
      }

      if (waitingForOperand) {
        setCurrentValue(digit);
        setWaitingForOperand(false);
      } else {
        if (currentValue === '0') {
          setCurrentValue(digit);
        } else {
          if (currentValue.replace(/[-.]/g, '').length < MAX_DIGITS) {
            setCurrentValue((prev) => prev + digit);
          }
        }
      }
      setIsClearAll(false);
    },
    [currentValue, waitingForOperand]
  );

  // 小数点入力
  const handleDecimal = useCallback(() => {
    if (currentValue === 'エラー') {
      setCurrentValue('0.');
      setWaitingForOperand(false);
      setIsClearAll(false);
      return;
    }

    if (waitingForOperand) {
      setCurrentValue('0.');
      setWaitingForOperand(false);
    } else if (!currentValue.includes('.')) {
      setCurrentValue((prev) => prev + '.');
    }
    setIsClearAll(false);
  }, [currentValue, waitingForOperand]);

  // 演算子選択 (+, -, ×, ÷)
  const handleOperator = useCallback(
    (nextOperator: '+' | '-' | '×' | '÷') => {
      if (currentValue === 'エラー') return;

      if (operator && waitingForOperand) {
        // 直前の演算子変更
        setOperator(nextOperator);
        setExpression(`${previousValue} ${nextOperator}`);
        return;
      }

      if (previousValue !== null && operator) {
        // 連続計算
        const { resultStr, error } = executeCalculation(previousValue, currentValue, operator);
        if (error) {
          setCurrentValue('エラー');
          setPreviousValue(null);
          setOperator(null);
          setWaitingForOperand(false);
          setExpression('');
          setIsClearAll(true);
          return;
        }

        addHistoryItem(`${previousValue} ${operator} ${currentValue} =`, resultStr);

        setCurrentValue(resultStr);
        setPreviousValue(resultStr);
        setExpression(`${resultStr} ${nextOperator}`);
      } else {
        setPreviousValue(currentValue);
        setExpression(`${currentValue} ${nextOperator}`);
      }

      setWaitingForOperand(true);
      setOperator(nextOperator);
      setIsClearAll(false);
    },
    [addHistoryItem, currentValue, executeCalculation, operator, previousValue, waitingForOperand]
  );

  // イコール計算
  const handleEquals = useCallback(() => {
    if (!operator || previousValue === null || currentValue === 'エラー') {
      return;
    }

    const { resultStr, error } = executeCalculation(previousValue, currentValue, operator);

    if (error) {
      setCurrentValue('エラー');
      setPreviousValue(null);
      setOperator(null);
      setWaitingForOperand(false);
      setExpression(`${previousValue} ${operator} ${currentValue} =`);
      setIsClearAll(true);
      return;
    }

    const expr = `${previousValue} ${operator} ${currentValue} =`;
    addHistoryItem(expr, resultStr);

    setExpression(expr);
    setCurrentValue(resultStr);
    setPreviousValue(null);
    setOperator(null);
    setWaitingForOperand(true);
    setIsClearAll(true);
  }, [addHistoryItem, currentValue, executeCalculation, operator, previousValue]);

  // C: 現在の入力のみクリア
  const handleClear = useCallback(() => {
    setCurrentValue('0');
    setIsClearAll(true);
  }, []);

  // AC: 全てクリア
  const handleAllClear = useCallback(() => {
    setCurrentValue('0');
    setPreviousValue(null);
    setOperator(null);
    setWaitingForOperand(false);
    setExpression('');
    setIsClearAll(true);
  }, []);

  // 符号反転
  const handleToggleSign = useCallback(() => {
    if (currentValue === 'エラー' || currentValue === '0') return;

    if (currentValue.startsWith('-')) {
      setCurrentValue(currentValue.slice(1));
    } else {
      setCurrentValue('-' + currentValue);
    }
  }, [currentValue]);

  // パーセント計算
  const handlePercent = useCallback(() => {
    if (currentValue === 'エラー') return;
    const num = parseFloat(currentValue);
    if (isNaN(num)) return;

    let res = num / 100;
    if (previousValue !== null && operator) {
      const prev = parseFloat(previousValue);
      if (!isNaN(prev) && (operator === '+' || operator === '-')) {
        res = (prev * num) / 100;
      }
    }
    const sanitized = sanitizeNumber(res);
    setCurrentValue(sanitized);
    setIsClearAll(false);
  }, [currentValue, operator, previousValue]);

  // 履歴から再利用
  const handleSelectHistory = useCallback((item: CalculationHistory) => {
    if (item.result === 'エラー') return;
    setCurrentValue(item.result);
    setWaitingForOperand(false);
    setIsClearAll(false);
  }, []);

  // 履歴消去
  const handleClearHistory = useCallback(() => {
    setHistory([]);
  }, []);

  // キーボードイベントのリスナー
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const { key } = e;

      if (/^[0-9]$/.test(key)) {
        e.preventDefault();
        handleDigit(key);
      } else if (key === '.' || key === 'Decimal') {
        e.preventDefault();
        handleDecimal();
      } else if (key === '+' || key === '-') {
        e.preventDefault();
        handleOperator(key as '+' | '-');
      } else if (key === '*' || key === 'Multiply') {
        e.preventDefault();
        handleOperator('×');
      } else if (key === '/' || key === 'Divide') {
        e.preventDefault();
        handleOperator('÷');
      } else if (key === 'Enter' || key === '=') {
        e.preventDefault();
        handleEquals();
      } else if (key === 'Escape') {
        e.preventDefault();
        handleAllClear();
      } else if (key === 'c' || key === 'C') {
        e.preventDefault();
        if (isClearAll) {
          handleAllClear();
        } else {
          handleClear();
        }
      } else if (key === 'Backspace') {
        e.preventDefault();
        if (currentValue !== 'エラー' && !waitingForOperand) {
          if (currentValue.length > 1) {
            setCurrentValue((prev) => prev.slice(0, -1));
          } else {
            setCurrentValue('0');
            setIsClearAll(true);
          }
        }
      } else if (key === '%' || key === 'p' || key === 'P') {
        e.preventDefault();
        handlePercent();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [
    currentValue,
    handleAllClear,
    handleClear,
    handleDecimal,
    handleDigit,
    handleEquals,
    handleOperator,
    handlePercent,
    isClearAll,
    waitingForOperand,
  ]);

  return (
    <div className="calculator-app">
      <div className="calculator-card">
        <div style={{ display: 'flex', flexDirection: 'column', flex: 1 }}>
          <Display expression={expression} currentValue={currentValue} />
          <Keypad
            onDigit={handleDigit}
            onDecimal={handleDecimal}
            onOperator={handleOperator}
            onEquals={handleEquals}
            onClear={handleClear}
            onAllClear={handleAllClear}
            onToggleSign={handleToggleSign}
            onPercent={handlePercent}
            isClearAll={isClearAll}
            activeOperator={waitingForOperand ? operator : null}
          />
        </div>
        <HistoryList
          history={history}
          onSelectHistory={handleSelectHistory}
          onClearHistory={handleClearHistory}
        />
      </div>
    </div>
  );
};

export default App;
